namespace sv_1331ed2bdcfc4aa7891b189924caee05.Services;

public class WarehouseStateService
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        Warehouses.TryGetValue(_currentWarehouseId, out var name) ? name : _currentWarehouseId;

    public event Action? OnChange;

    public static readonly Dictionary<string, string> Warehouses = new()
    {
        ["WH-001"] = "Warehouse A - Downtown",
        ["WH-002"] = "Warehouse B - Airport",
        ["WH-003"] = "Warehouse C - Harbor",
        ["WH-004"] = "Warehouse D - Industrial Park"
    };

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_1331ed2bdcfc4aa7891b189924caee05.Services;

public class InventoryAlertService
{
    private readonly Random _random = new();
    private int _lastLowStockCount;

    public int LastLowStockCount => _lastLowStockCount;

    public event Action? OnAlertCountChanged;

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulates a database query returning a random count of low-stock items
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    public void UpdateAlertCount(int count)
    {
        _lastLowStockCount = count;
        OnAlertCountChanged?.Invoke();
    }
}

