@rendermode InteractiveServer
@inject Services.WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label class="form-label mb-0 text-white me-2">Site:</label>
    <select class="form-select form-select-sm" value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in Services.WarehouseStateService.Warehouses)
        {
            <option value="@wh.Key">@wh.Value</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.SetWarehouse(newId);
        }
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

@rendermode InteractiveServer
@inject Services.InventoryAlertService AlertService
@implements IDisposable

<span class="alert-badge">
    @if (AlertService.LastLowStockCount > 0)
    {
        <span class="badge bg-danger rounded-pill">@AlertService.LastLowStockCount</span>
    }
